export class AppError extends Error {
  constructor(status, code, message, { expose = status < 500, cause } = {}) {
    super(message, { cause });
    this.status = status;
    this.code = code;
    this.expose = expose; // safe to show message to the client?
  }
}

export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err); // let Express close the connection

  const status = err.status ?? err.statusCode ?? 500;
  if (status >= 500) req.log.error({ err }, 'request failed');
  else req.log.warn({ err: { code: err.code, message: err.message } }, 'client error');

  res.status(status).json({
    error: {
      code: err.code ?? (status >= 500 ? 'INTERNAL' : 'BAD_REQUEST'),
      message: err.expose ? err.message : 'Something went wrong',
      requestId: req.id,
    },
  });
}

