    const key = newKey();                       // never use info.filename as a path
    let tooBig = false;
    file.on('limit', () => { tooBig = true; }); // busboy truncates the stream here
    try {
      await pipeline(file, storage.createWriteStream(key)); // e.g. S3 multipart upload stream
      if (tooBig) {
        await storage.remove(key);
        return res.status(413).json({ error: { code: 'FILE_TOO_LARGE' } });
